service.method:

SELECT
	SEAL_MG_USER_ID
	, GETUSERNAME(HOUSE_CODE, COMPANY_CODE, SEAL_MG_USER_ID, 'KO') AS SEAL_MG_USER_NAME
	, GETUSERDEPTNAME(HOUSE_CODE, COMPANY_CODE, SEAL_MG_USER_ID, 'KO') AS SEAL_MG_DEPT_NAME
	, ( select `position` from SUSMT where USER_ID = SEAL_MG_USER_ID and HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
	  ) AS SEAL_MG_USER_POSITION
	, ( select `employee_no` from SUSMT where USER_ID = SEAL_MG_USER_ID and HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
	  ) AS SEAL_MG_EMPLOYEE_NO 
	, SUB_MG_USER_ID 
	, GETUSERNAME(HOUSE_CODE, COMPANY_CODE, SUB_MG_USER_ID, 'KO') AS SUB_MG_USER_NAME
	, GETUSERDEPTNAME(HOUSE_CODE, COMPANY_CODE, SUB_MG_USER_ID, 'KO') AS SUB_MG_DEPT_NAME
	, ( select `position` from SUSMT where USER_ID = SUB_MG_USER_ID and HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
	  ) AS SUB_MG_USER_POSITION
  	, ( select `employee_no` from SUSMT where USER_ID = SUB_MG_USER_ID and HOUSE_CODE = ${session.HOUSE_CODE}
			AND COMPANY_CODE = ${session.COMPANY_CODE}
	  ) AS SUB_MG_EMPLOYEE_NO
FROM
	SSEAL 
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND MANAGE_NUMBER IN ($INS{manageNo_Arr})
	AND SEAL_TYPE = $S{SEAL_TYPE}


SELECT
	SUBJECT
FROM
	SUDGL
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND USE_NUMBER = ${SEAL_USE_TYPE}


SELECT
	SMI_NUMBER
	, SUBJECT
FROM
	SSRAD
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMI_NUMBER = ${SMI_NUMBER}


SELECT
	SMR_NUMBER
	,DATA
FROM
	SSIAD_EXTRA_INFO
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMR_NUMBER = ${SMR_NUMBER}


SELECT 
	APP_NO
FROM 
	SGWGL 
WHERE 
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SUX_WKEY1 = ${SMR_NUMBER}
ORDER BY
	APP_NO DESC


SELECT
	*
FROM
	SSIAD
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMR_NUMBER = ${SMR_NUMBER}


SELECT
	*
FROM
	SSETL
WHERE
	HOUSE_CODE = ${session.HOUSE_CODE}
	AND COMPANY_CODE = ${session.COMPANY_CODE}
	AND SMR_NUMBER = ${SMR_NUMBER}
